import { z } from 'zod';
import { transform } from '../api/scans';

export const MAX_CAPTURE_FILE_BYTES = 32 * 1024 * 1024;
export const MAX_CAPTURE_BYTES = 256 * 1024 * 1024;
export const MAX_CAPTURE_JSON_BYTES = 2 * 1024 * 1024;
export const MAX_CAPTURE_FRAMES = 1000;
export const REQUIRED_CAPTURE_FILES = ['source.glb', 'points.ply', 'frames.json', 'preview.jpg'] as const;
const frameId = z.string().regex(/^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$/);

// No decoding/normalization: reject ambiguous paths rather than trying to repair them.
export const capturePath = z.string().max(160).refine(value =>
  (REQUIRED_CAPTURE_FILES as readonly string[]).includes(value) ||
  /^frames\/[A-Za-z0-9][A-Za-z0-9_-]{0,127}\.jpg$/.test(value), 'Unsupported or unsafe capture path');
export const fileDigest = z.object({
  byteSize: z.number().int().positive().max(MAX_CAPTURE_FILE_BYTES),
  sha256: z.string().regex(/^[0-9a-f]{64}$/),
}).strict();

export const captureManifest = z.object({
  version: z.literal(1), captureId: z.uuid(),
  device: z.object({ model: z.string().min(1).max(200), osVersion: z.string().min(1).max(100) }).strict(),
  coordinateSystem: z.object({
    units: z.literal('metres'), upAxis: z.literal('Y'), handedness: z.literal('right'),
    matrixLayout: z.literal('column-major'), poseConvention: z.literal('camera-to-capture'),
  }).strict(),
  entrancePose: transform,
  capturedAt: z.iso.datetime({ offset: true }).optional(),
  trackingWarnings: z.array(z.string().min(1).max(1000)).max(100).default([]),
  files: z.array(fileDigest.extend({ path: capturePath }).strict()).min(5).max(MAX_CAPTURE_FRAMES + 4),
}).strict().superRefine((manifest, ctx) => {
  const paths = new Set(manifest.files.map(file => file.path));
  if (paths.size !== manifest.files.length) ctx.addIssue({ code: 'custom', message: 'Duplicate file paths' });
  for (const required of REQUIRED_CAPTURE_FILES) {
    if (!paths.has(required)) ctx.addIssue({ code: 'custom', message: `Missing required file: ${required}` });
  }
  if (manifest.files.reduce((sum, file) => sum + file.byteSize, 0) > MAX_CAPTURE_BYTES) {
    ctx.addIssue({ code: 'custom', message: 'Capture exceeds 256 MiB' });
  }
  const frames = manifest.files.find(file => file.path === 'frames.json');
  if (frames && frames.byteSize > MAX_CAPTURE_JSON_BYTES) {
    ctx.addIssue({ code: 'custom', message: 'frames.json exceeds 2 MiB' });
  }
});

export const captureRegistration = z.object({ spaceId: z.uuid(), manifest: captureManifest }).strict();
export type CaptureManifest = z.infer<typeof captureManifest>;
export type FileDigest = z.infer<typeof fileDigest>;

export const captureFrameIndex = z.object({
  version: z.literal(1), captureId: z.uuid(),
  frames: z.array(z.object({
    id: frameId, imagePath: capturePath, cameraPose: transform,
    timestampSeconds: z.number().finite().nonnegative(),
    width: z.number().int().positive().max(32768), height: z.number().int().positive().max(32768),
    intrinsics: z.object({
      fx: z.number().finite().positive(), fy: z.number().finite().positive(),
      cx: z.number().finite(), cy: z.number().finite(),
    }).strict().optional(),
  }).strict()).min(1).max(MAX_CAPTURE_FRAMES),
}).strict().superRefine((index, ctx) => {
  if (new Set(index.frames.map(frame => frame.id)).size !== index.frames.length) {
    ctx.addIssue({ code: 'custom', message: 'Duplicate frame IDs' });
  }
  for (const frame of index.frames) {
    if (frame.imagePath !== `frames/${frame.id}.jpg`) {
      ctx.addIssue({ code: 'custom', message: 'Frame imagePath must match its stable ID' });
    }
  }
});

export function validateFrameReferences(value: unknown, manifest: CaptureManifest) {
  return captureFrameIndex.superRefine((index, ctx) => {
    if (index.captureId !== manifest.captureId) ctx.addIssue({ code: 'custom', message: 'Frame capture ID does not match manifest' });
    const images = new Set(manifest.files.filter(file => file.path.startsWith('frames/')).map(file => file.path));
    if (index.frames.length !== images.size || index.frames.some(frame => !images.has(frame.imagePath))) {
      ctx.addIssue({ code: 'custom', message: 'Every manifest frame image must have exactly one frame reference' });
    }
  }).parse(value);
}

// Normalize object key ordering for retry identity, while retaining array order.
export function canonicalJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  if (value !== null && typeof value === 'object') {
    return `{${Object.entries(value).filter(([, v]) => v !== undefined).sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0)
      .map(([key, v]) => `${JSON.stringify(key)}:${canonicalJson(v)}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

import { constants } from 'node:fs';
import { link, lstat, mkdir, open, realpath, unlink } from 'node:fs/promises';
import { createHash, randomUUID } from 'node:crypto';
import path from 'node:path';
import { capturePath, type FileDigest } from '../capture/contract';

export class CaptureIntegrityError extends Error {}
export interface CaptureStorage {
  // Implementations must verify size/hash before atomically making immutable bytes visible.
  // S3 implementations can stage, verify and conditionally copy to a final private key.
  putVerified(key: string, chunks: AsyncIterable<Uint8Array>, expected: FileDigest): Promise<void>;
  inspect(key: string): Promise<FileDigest | null>;
  read(key: string, maxBytes: number): Promise<Uint8Array>;
}

export function captureObjectKey(captureId: string, relativePath: string) {
  if (!/^[0-9a-f-]{36}$/.test(captureId)) throw new Error('Invalid capture storage ID');
  if (relativePath !== 'manifest.json') capturePath.parse(relativePath);
  return `captures/${captureId}/${relativePath}`;
}

export class LocalCaptureStorage implements CaptureStorage {
  constructor(private readonly root: string) {}

  private async file(key: string, create: boolean) {
    const match = /^captures\/([0-9a-f-]{36})\/(.+)$/.exec(key);
    if (!match || key !== captureObjectKey(match[1], match[2])) throw new Error('Invalid capture object key');
    // Storage is an application-owned private directory, never a public/ web directory.
    const root = path.resolve(this.root);
    if (create) await mkdir(root, { recursive: true, mode: 0o700 });
    const actualRoot = await realpath(root);
    let current = actualRoot;
    const parts = key.split('/');
    for (const part of parts.slice(0, -1)) {
      current = path.join(current, part);
      if (create) await mkdir(current, { mode: 0o700 }).catch(error => {
        if (error.code !== 'EEXIST') throw error;
      });
      const info = await lstat(current);
      if (!info.isDirectory() || info.isSymbolicLink()) throw new Error('Unsafe capture storage directory');
    }
    return path.join(current, parts.at(-1)!);
  }

  async putVerified(key: string, chunks: AsyncIterable<Uint8Array>, expected: FileDigest) {
    const file = await this.file(key, true);
    const temporary = `${file}.${randomUUID()}.tmp`;
    const handle = await open(temporary, 'wx', 0o600);
    let byteSize = 0;
    const hash = createHash('sha256');
    try {
      for await (const chunk of chunks) {
        byteSize += chunk.byteLength;
        if (byteSize > expected.byteSize) throw new CaptureIntegrityError('File exceeds declared byte size');
        hash.update(chunk);
        // FileHandle.write may write fewer bytes than requested.
        let offset = 0;
        while (offset < chunk.byteLength) {
          const { bytesWritten } = await handle.write(chunk, offset, chunk.byteLength - offset);
          if (!bytesWritten) throw new Error('Capture storage write made no progress');
          offset += bytesWritten;
        }
      }
      if (byteSize !== expected.byteSize) throw new CaptureIntegrityError('File does not match declared byte size');
      if (hash.digest('hex') !== expected.sha256) throw new CaptureIntegrityError('File does not match declared SHA-256');
      await handle.sync();
      await handle.close();
      // Hard-link promotion is atomic and never overwrites an already accepted object.
      try { await link(temporary, file); }
      catch (error) {
        if ((error as NodeJS.ErrnoException).code !== 'EEXIST') throw error;
        const existing = await this.inspect(key);
        if (!existing || existing.byteSize !== expected.byteSize || existing.sha256 !== expected.sha256) {
          throw new CaptureIntegrityError('Existing capture object has different bytes');
        }
      }
    } finally {
      await handle.close().catch(() => {});
      await unlink(temporary).catch(error => { if (error.code !== 'ENOENT') throw error; });
    }
  }

  async inspect(key: string): Promise<FileDigest | null> {
    let handle;
    try {
      handle = await open(await this.file(key, false), constants.O_RDONLY | constants.O_NOFOLLOW);
      if (!(await handle.stat()).isFile()) throw new Error('Capture object is not a regular file');
      const hash = createHash('sha256');
      let byteSize = 0;
      for await (const chunk of handle.createReadStream()) { byteSize += chunk.length; hash.update(chunk); }
      return { byteSize, sha256: hash.digest('hex') };
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw error;
    } finally { await handle?.close().catch(() => {}); }
  }

  async read(key: string, maxBytes: number) {
    const handle = await open(await this.file(key, false), constants.O_RDONLY | constants.O_NOFOLLOW);
    try {
      const chunks: Buffer[] = [];
      let size = 0;
      for await (const chunk of handle.createReadStream()) {
        size += chunk.length;
        if (size > maxBytes) throw new CaptureIntegrityError('Capture JSON exceeds size limit');
        chunks.push(chunk);
      }
      return Buffer.concat(chunks, size);
    } finally { await handle.close().catch(() => {}); }
  }
}

export function captureStorage(): CaptureStorage {
  return new LocalCaptureStorage(path.resolve(process.env.CAPTURE_STORAGE_DIR || path.join(process.cwd(), '.local-captures')));
}

