import { OrbitControls } from "@react-three/drei";
import { Canvas, useThree } from "@react-three/fiber";
import { useEffect, useMemo } from "react";
import { CanvasTexture, MathUtils, MOUSE, TOUCH, type Texture, type Vector3 } from "three";
import type { PointScan } from "../lib/ply";

const NIGHT = "#121C16";

/** The parts of drei's OrbitControls that framing touches. */
interface OrbitLike {
  target: Vector3;
  minDistance: number;
  maxDistance: number;
  update(): void;
}

/** A soft round sprite so points read as dots rather than squares. */
function useDotTexture(): Texture {
  return useMemo(() => {
    const size = 64;
    const canvas = document.createElement("canvas");
    canvas.width = canvas.height = size;
    const ctx = canvas.getContext("2d");
    if (ctx) {
      ctx.beginPath();
      ctx.arc(size / 2, size / 2, size / 2 - 1, 0, Math.PI * 2);
      ctx.fillStyle = "#ffffff";
      ctx.fill();
    }
    return new CanvasTexture(canvas);
  }, []);
}

/**
 * World-space point size from scan density: sparse scans (like the 93-point fixture)
 * get large dots so shapes stay readable, dense phone scans get fine ones.
 */
function pointSizeFor(scan: PointScan): number {
  const spacing = scan.bounds.radius / Math.sqrt(scan.count);
  return MathUtils.clamp(spacing * 0.7, 0.008, 0.3);
}

function Points({ scan }: { scan: PointScan }) {
  const dot = useDotTexture();
  const size = pointSizeFor(scan);
  useEffect(() => () => dot.dispose(), [dot]);
  return (
    <points geometry={scan.geometry} frustumCulled={false}>
      <pointsMaterial
        size={size}
        sizeAttenuation
        vertexColors={scan.hasColor}
        color={scan.hasColor ? "#ffffff" : "#A9C4AE"}
        map={dot}
        alphaTest={0.5}
        transparent={false}
      />
    </points>
  );
}

/**
 * Frames the scan from behind and above the entrance. The event frame puts the
 * entrance at the origin with −Z forward, so a camera on +Z looks down the corridor
 * the way a guest walking in would.
 */
function Framing({ scan, resetToken }: { scan: PointScan; resetToken: number }) {
  const camera = useThree((s) => s.camera);
  const controls = useThree((s) => s.controls) as unknown as OrbitLike | null;

  useEffect(() => {
    const { center, radius } = scan.bounds;
    // Fit the bounding sphere on narrow (portrait phone) screens too: use the
    // smaller of the vertical and horizontal fields of view.
    const perspective = camera as typeof camera & { fov?: number; aspect?: number };
    const vFov = MathUtils.degToRad(perspective.fov ?? 55);
    const hFov = 2 * Math.atan(Math.tan(vFov / 2) * (perspective.aspect ?? 1));
    const distance = (radius / Math.sin(Math.min(vFov, hFov) / 2)) * 0.85;
    // About 24° above the floor, behind the entrance: low enough to read doorways as
    // standing shapes, high enough to see the corridor layout.
    camera.position.set(center.x, center.y + distance * 0.4, center.z + distance * 0.92);
    camera.near = Math.max(radius / 1000, 0.001);
    camera.far = radius * 50;
    camera.updateProjectionMatrix();
    if (controls) {
      controls.target.copy(center);
      controls.minDistance = radius * 0.05;
      controls.maxDistance = radius * 6;
      controls.update();
    } else {
      camera.lookAt(center);
    }
  }, [scan, camera, controls, resetToken]);

  return null;
}

export interface ScanViewerProps {
  scan: PointScan;
  /** Change this number to put the camera back to the starting view. */
  resetToken: number;
}

export default function ScanViewer({ scan, resetToken }: ScanViewerProps) {
  return (
    <Canvas
      dpr={[1, 2]}
      camera={{ fov: 55 }}
      gl={{ antialias: true, powerPreference: "high-performance" }}
      aria-hidden="true"
    >
      <color attach="background" args={[NIGHT]} />
      <Points scan={scan} />
      <OrbitControls
        makeDefault
        enableDamping
        dampingFactor={0.08}
        rotateSpeed={0.7}
        zoomSpeed={0.9}
        maxPolarAngle={Math.PI * 0.92}
        touches={{ ONE: TOUCH.ROTATE, TWO: TOUCH.DOLLY_PAN }}
        mouseButtons={{ LEFT: MOUSE.ROTATE, MIDDLE: MOUSE.DOLLY, RIGHT: MOUSE.PAN }}
      />
      <Framing scan={scan} resetToken=REDACTED />
    </Canvas>
  );
}
import { Box3, Group, LoadingManager, Material, Matrix4, Mesh, Texture } from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";

export class ModelParseError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ModelParseError";
  }
}

/** Validate before GLTFLoader sees the document: uploads must be self-contained. */
export function validateGlb(buffer: ArrayBuffer): void {
  const view = new DataView(buffer);
  if (buffer.byteLength < 20 || view.getUint32(0, true) !== 0x46546c67) {
    throw new ModelParseError("The file is not a binary GLB model.");
  }
  if (view.getUint32(4, true) !== 2 || view.getUint32(8, true) !== buffer.byteLength) {
    throw new ModelParseError("The GLB version or declared file length is invalid.");
  }
  let document: unknown;
  let offset = 12;
  while (offset < buffer.byteLength) {
    if (offset + 8 > buffer.byteLength) throw new ModelParseError("The GLB has a truncated chunk.");
    const length = view.getUint32(offset, true);
    const type = view.getUint32(offset + 4, true);
    if (length % 4 !== 0 || offset + 8 + length > buffer.byteLength) {
      throw new ModelParseError("The GLB has an invalid chunk length.");
    }
    if (offset === 12) {
      if (type !== 0x4e4f534a) throw new ModelParseError("The GLB is missing its JSON chunk.");
      try {
        document = JSON.parse(new TextDecoder().decode(new Uint8Array(buffer, offset + 8, length)));
      } catch {
        throw new ModelParseError("The GLB contains invalid JSON.");
      }
    }
    offset += 8 + length;
  }
  if (!document || typeof document !== "object") throw new ModelParseError("The GLB document is empty.");
  // Check extensions too. No model-authored remote/file URL may bypass the API's
  // asset authorization or contact a third party when a visitor opens a space.
  function checkUris(value: unknown): void {
    if (!value || typeof value !== "object") return;
    for (const [key, child] of Object.entries(value)) {
      if (key === "uri" && (typeof child !== "string" || !child.startsWith("data:"))) {
        throw new ModelParseError("The GLB references an external file. Export with embedded buffers and textures.");
      }
      checkUris(child);
    }
  }
  checkUris(document);
}

/** Column-major, affine scan-to-space matrix; translation occupies indices 12–14. */
export function scanMatrix(elements: readonly number[]): Matrix4 {
  if (elements.length !== 16 || !elements.every(Number.isFinite) ||
      elements[3] !== 0 || elements[7] !== 0 || elements[11] !== 0 || elements[15] !== 1) {
    throw new ModelParseError("The scan alignment must be a finite, affine 4×4 matrix.");
  }
  const matrix = new Matrix4().fromArray(elements);
  const scale = Math.max(...[0, 1, 2, 4, 5, 6, 8, 9, 10].map(i => Math.abs(elements[i]!)));
  const normalized = elements.map(value => value / scale);
  const determinant = normalized[0]! * (normalized[5]! * normalized[10]! - normalized[9]! * normalized[6]!)
    - normalized[4]! * (normalized[1]! * normalized[10]! - normalized[9]! * normalized[2]!)
    + normalized[8]! * (normalized[1]! * normalized[6]! - normalized[5]! * normalized[2]!);
  if (!Number.isFinite(determinant) || Math.abs(determinant) <= Number.EPSILON) {
    throw new ModelParseError("The scan alignment has zero scale and cannot be displayed.");
  }
  return matrix;
}

export interface GlbModel {
  /** Wrapper applies alignment while preserving every GLTF node transform. */
  object: Group;
  bounds: Box3;
  dispose(): void;
}

export function disposeModel(root: Group): void {
  const materials = new Set<Material>();
  const textures = new Set<Texture>();
  root.traverse((object) => {
    if (!(object instanceof Mesh)) return;
    object.geometry.dispose();
    for (const material of Array.isArray(object.material) ? object.material : [object.material]) {
      materials.add(material);
      for (const value of Object.values(material)) if (value instanceof Texture) textures.add(value);
    }
  });
  for (const material of materials) material.dispose();
  for (const texture of textures) {
    texture.dispose();
    const image = texture.source.data as { close?: () => void } | undefined;
    image?.close?.();
  }
}

export async function parseGlb(buffer: ArrayBuffer, transform: readonly number[]): Promise<GlbModel> {
  validateGlb(buffer);
  const matrix = scanMatrix(transform);
  const manager = new LoadingManager();
  let resourceFailed = false;
  manager.onError = () => { resourceFailed = true; };
  manager.setURLModifier((url) => {
    // GLTFLoader creates blob URLs for embedded image bufferViews.
    if (!url.startsWith("blob:") && !url.startsWith("data:")) {
      throw new ModelParseError("External GLB resources are not allowed.");
    }
    return url;
  });
  const gltf = await new GLTFLoader(manager).parseAsync(buffer, "");
  const object = new Group();
  object.matrixAutoUpdate = false;
  object.matrix.copy(matrix);
  object.add(gltf.scene);
  try {
    if (resourceFailed) throw new ModelParseError("An embedded texture or buffer could not be decoded. Re-export the GLB with valid embedded resources.");
    let vertices = 0;
    object.traverse((child) => {
      if (!(child instanceof Mesh)) return;
      const positions = child.geometry.getAttribute("position");
      if (!positions) return;
      vertices += positions.count;
      for (let i = 0; i < positions.count; i++) {
        if (![positions.getX(i), positions.getY(i), positions.getZ(i)].every(Number.isFinite)) {
          throw new ModelParseError("The GLB has invalid vertex coordinates.");
        }
      }
    });
    object.updateMatrixWorld(true);
    const bounds = new Box3().setFromObject(object);
    if (!vertices || bounds.isEmpty() || ![...bounds.min.toArray(), ...bounds.max.toArray()].every(Number.isFinite)) {
      throw new ModelParseError("The GLB has no usable mesh geometry.");
    }
    return { object, bounds, dispose: () => disposeModel(object) };
  } catch (error) {
    disposeModel(object);
    throw error;
  }
}
/**
 * Client for the share endpoints in services/api/README.md.
 *
 *   GET /api/shares/<shareId>        -> { shareId, format, assetPath }
 *   GET /api/shares/<shareId>/asset  -> the uploaded file (same access check)
 *
 * The API answers 404 both for an unknown share and for a private share the
 * viewer may not open, so the UI treats those as one "not found or no access" state.
 */

export type ScanFormat = "ply" | "glb";

export interface ShareMetadata {
  shareId: string;
  format: ScanFormat;
  assetPath: string;
}

export type ShareErrorKind = "not-found" | "network" | "server" | "bad-response";

export class ShareError extends Error {
  readonly kind: ShareErrorKind;
  readonly status?: number;

  constructor(kind: ShareErrorKind, message: string, status?: number) {
    super(message);
    this.name = "ShareError";
    this.kind = kind;
    this.status = status;
  }
}

async function request(url: string, signal: AbortSignal): Promise<Response> {
  let response: Response;
  try {
    response = await fetch(url, { signal, credentials: "same-origin" });
  } catch (error) {
    if (signal.aborted) throw error;
    throw new ShareError("network", "Could not reach the Path server.");
  }
  if (response.status === 404) {
    throw new ShareError("not-found", "This scan link doesn't exist or isn't shared with you.", 404);
  }
  if (!response.ok) {
    throw new ShareError("server", `The server answered ${response.status}.`, response.status);
  }
  return response;
}

function isShareMetadata(value: unknown): value is ShareMetadata {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.shareId === "string" &&
    (v.format === "ply" || v.format === "glb") &&
    typeof v.assetPath === "string" &&
    v.assetPath.length > 0
  );
}

export async function fetchShare(shareId: string, signal: AbortSignal): Promise<ShareMetadata> {
  const response = await request(`/api/shares/${encodeURIComponent(shareId)}`, signal);
  let body: unknown;
  try {
    body = await response.json();
  } catch {
    throw new ShareError("bad-response", "The share details weren't valid JSON.");
  }
  if (!isShareMetadata(body)) {
    throw new ShareError("bad-response", "The share details were missing a format or asset path.");
  }
  return body;
}

/** Fetches the scan bytes. `assetPath` may be relative to this site or an absolute URL. */
export async function fetchAsset(assetPath: string, signal: AbortSignal): Promise<ArrayBuffer> {
  const url = new URL(assetPath, window.location.origin).toString();
  const response = await request(url, signal);
  try {
    return await response.arrayBuffer();
  } catch (error) {
    if (signal.aborted) throw error;
    throw new ShareError("network", "The scan download was interrupted.");
  }
}
