function Overlays({ nodes, edges, route, showGraph, radius }: {
  nodes: ViewerNode[]; edges: ViewerEdge[]; route: ViewerNode[]; showGraph: boolean; radius: number;
}) {
  const byId = new Map(nodes.filter(finite).map((node) => [node.id, node]));
